From 9030e70a7192303d0811dd5ebb319f94f07b35cf Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:51:46 +0100
Subject: [PATCH] plasmacalendarintegration: show the language of holiday
 regions

Countries with one holiday file per language, like Belgium or Bangladesh,
were listed as several identical rows in the Holidays settings page. The
language name is now shown in the subtitle of those regions.

BUG: 482125
---
 plasmacalendarintegration/HolidaysConfig.qml  |  2 +-
 .../qmlhelper/CMakeLists.txt                  |  2 ++
 .../qmlhelper/holidayregionsconfig.cpp        | 34 +++++++++++++++++++
 .../qmlhelper/holidayregionsconfig.h          |  3 ++
 4 files changed, 40 insertions(+), 1 deletion(-)

diff --git a/plasmacalendarintegration/HolidaysConfig.qml b/plasmacalendarintegration/HolidaysConfig.qml
index 8d5335af54..38479a7bf6 100644
--- a/plasmacalendarintegration/HolidaysConfig.qml
+++ b/plasmacalendarintegration/HolidaysConfig.qml
@@ -68,7 +68,7 @@ KCMUtils.ScrollViewKCM {
             property string subtitle

             text: name
-            subtitle: description
+            subtitle: [configHelper.languageName(region), description].filter(Boolean).join(" · ")

             checked: configHelper.selectedRegions.includes(region)
             width: ListView.view.width
diff --git a/plasmacalendarintegration/qmlhelper/CMakeLists.txt b/plasmacalendarintegration/qmlhelper/CMakeLists.txt
index ec71a7159e..2a63c7578d 100644
--- a/plasmacalendarintegration/qmlhelper/CMakeLists.txt
+++ b/plasmacalendarintegration/qmlhelper/CMakeLists.txt
@@ -14,6 +14,8 @@ target_link_libraries(holidayevents
         Qt::Qml
         Qt::Core
         KF6::ConfigCore
+        KF6::ConfigWidgets
+        KF6::Holidays
 )

 ecm_finalize_qml_module(holidayevents
diff --git a/plasmacalendarintegration/qmlhelper/holidayregionsconfig.cpp b/plasmacalendarintegration/qmlhelper/holidayregionsconfig.cpp
index b06b59c95d..abc9683627 100644
--- a/plasmacalendarintegration/qmlhelper/holidayregionsconfig.cpp
+++ b/plasmacalendarintegration/qmlhelper/holidayregionsconfig.cpp
@@ -7,14 +7,29 @@

 #include "holidayregionsconfig.h"

+#include <KHolidays/HolidayRegion>
+#include <KLanguageName>
 #include <KSharedConfig>

+#include <QLocale>
+
+static QString countryPart(const QString &region)
+{
+    return region.left(region.lastIndexOf(QLatin1Char('_')));
+}
+
 HolidayRegionsConfig::HolidayRegionsConfig(QObject *parent)
     : QObject(parent)
 {
     KSharedConfig::Ptr config = KSharedConfig::openConfig(QStringLiteral("plasma_calendar_holiday_regions"));
     m_configGroup = config->group(QStringLiteral("General"));
     m_regions = m_configGroup.readEntry("selectedRegions", QStringList());
+
+    QStringList regionCodes = KHolidays::HolidayRegion::regionCodes();
+    regionCodes.removeDuplicates();
+    for (const QString &region : std::as_const(regionCodes)) {
+        m_filesPerCountry[countryPart(region)]++;
+    }
 }

 QStringList HolidayRegionsConfig::selectedRegions() const
@@ -43,4 +58,23 @@ void HolidayRegionsConfig::removeRegion(const QString &region)
     }
 }

+QString HolidayRegionsConfig::languageName(const QString &region) const
+{
+    if (m_filesPerCountry.value(countryPart(region)) < 2) {
+        return QString();
+    }
+
+    QString code = KHolidays::HolidayRegion::languageCode(region);
+    const qsizetype separator = code.indexOf(QLatin1Char('_'));
+    if (separator > 0) {
+        code = code.left(separator) + code.mid(separator).toUpper();
+    }
+
+    QString name = KLanguageName::nameForCode(code);
+    if (name.isEmpty()) {
+        name = QLocale::languageToString(QLocale(code).language());
+    }
+    return name;
+}
+
 #include "moc_holidayregionsconfig.cpp"
diff --git a/plasmacalendarintegration/qmlhelper/holidayregionsconfig.h b/plasmacalendarintegration/qmlhelper/holidayregionsconfig.h
index 1e3daed19a..8dca086ac8 100644
--- a/plasmacalendarintegration/qmlhelper/holidayregionsconfig.h
+++ b/plasmacalendarintegration/qmlhelper/holidayregionsconfig.h
@@ -7,6 +7,7 @@

 #pragma once

+#include <QHash>
 #include <QObject>
 #include <QStringList>
 #include <qqml.h>
@@ -27,6 +28,7 @@ public:
     Q_INVOKABLE void saveConfig();
     Q_INVOKABLE void addRegion(const QString &region);
     Q_INVOKABLE void removeRegion(const QString &region);
+    Q_INVOKABLE QString languageName(const QString &region) const;

 Q_SIGNALS:
     void selectedRegionsChanged();
@@ -34,4 +36,5 @@ Q_SIGNALS:
 private:
     QStringList m_regions;
     KConfigGroup m_configGroup;
+    QHash<QString, int> m_filesPerCountry;
 };
-- 
